from typing import Literal
from pydantic import BaseModel,Field

# Field generated by Gemini
class APIField(BaseModel):
    name: str=Field(...,description="Field Name")
    type:Literal[
        "string",
        "integer",
        "float",
        "boolean"
                 ]=Field(...,description="Field data type")
    required:bool=Field(...,description="Whether the field is required")

# Definition of API
class APISchema(BaseModel):
    resource_name: str = Field(..., description="Name of the API resource")
    description: str = Field(..., description="Short description of the API")
    fields: list[APIField] = Field(..., description="Fields in the API resource")

# What the developer sends -> A Request
class APIRequest(BaseModel):
    prompt: str = Field(
        ...,
        min_length=5,
        description="Natural-language description of the API to generate"
    )